use std::ffi::c_void;
extern "C" {
 fn shake8_create()->*mut c_void; fn shake8_clone(p:*const c_void)->*mut c_void;fn shake8_free(p:*mut c_void);
 fn shake8_absorb_same(p:*mut c_void,data:*const u8,n:usize)->i32;
 fn shake8_absorb8(p:*mut c_void,data:*const u8,n:usize,stride:usize)->i32;
 fn shake8_finalize(p:*mut c_void)->i32;
 fn shake8_squeeze8(p:*mut c_void,data:*mut u8,n:usize,stride:usize)->i32;
 fn shake8_words8(p:*mut c_void,data:*mut u64,n:usize)->i32;
 fn shake8_select_words8(p:*mut c_void,offsets:*const usize,data:*mut u64,n:usize)->i32;
}
struct Shake8(*mut c_void);
impl Drop for Shake8 {fn drop(&mut self){unsafe{shake8_free(self.0)}}}
impl Shake8{fn new()->Self{let p=unsafe{shake8_create()};assert!(!p.is_null());Self(p)}fn clone_ctx(&self)->Self{let p=unsafe{shake8_clone(self.0)};assert!(!p.is_null());Self(p)}fn same(&mut self,b:&[u8]){assert_eq!(unsafe{shake8_absorb_same(self.0,b.as_ptr(),b.len())},0);}fn different(&mut self,b:&[u8],n:usize){assert_eq!(b.len(),n*8);assert_eq!(unsafe{shake8_absorb8(self.0,b.as_ptr(),n,n)},0);}fn finalize(&mut self){assert_eq!(unsafe{shake8_finalize(self.0)},0);}fn squeeze(&mut self,n:usize)->Vec<u8>{let mut b=vec![0;n*8];assert_eq!(unsafe{shake8_squeeze8(self.0,b.as_mut_ptr(),n,n)},0);b}fn words(&mut self,n:usize)->Vec<Row>{let mut b=vec![Row([0;8]);n];assert_eq!(unsafe{shake8_words8(self.0,b.as_mut_ptr().cast(),n)},0);b}fn select(&mut self,offsets:[usize;8],n:usize)->Vec<Row>{let mut b=vec![Row([0;8]);n];assert_eq!(unsafe{shake8_select_words8(self.0,offsets.as_ptr(),b.as_mut_ptr().cast(),n)},0);b}}
fn record49(o:&Op)->[u8;49]{let mut b=[0;49];b[0]=o.kind as u8;for(i,v)in[o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0].iter().enumerate(){b[1+8*i..9+8*i].copy_from_slice(&v.to_le_bytes());}b}
fn tail(ops:&[Op],nonce:u64)->Vec<Op>{let mut t=ops[ops.len()-96..].to_vec();for pair in t.chunks_exact(2){assert_eq!(pair[0],pair[1]);assert_eq!(pair[0].kind,OperationType::X);assert_eq!(pair[0].c_condition.0,u64::MAX);}
 for(i,pair)in t.chunks_exact_mut(2).enumerate(){for o in pair{o.q_target=QubitId((nonce>>i)&1);o.validate();}}t}
fn fiat8(path:&str){
 let mut ops=load_ops(path).unwrap();let p=Compact::compile(&ops);let(nq,nb,_,regs)=analyze_ops(ops.iter());let start=ops.len()-96;
 // Eight predetermined labels are differential fixtures, never scored or
 // screened for success. Only the identity tail's target encodes the label.
 let nonces=[0u64,1,2,3,4,5,6,7];let tails:Vec<Vec<Op>>=nonces.iter().map(|n|tail(&ops,*n)).collect();
 let t=Instant::now();let mut s8=Shake8::new();let mut h=Shake256::default();for b in [b"quantum_ecc-fiat-shamir-v2".as_slice(),&(ops.len()as u64).to_le_bytes()]{s8.same(b);h.update(b);}
 let mut buf=Vec::with_capacity(49*32768);for o in &ops[..start]{buf.extend_from_slice(&record49(o));if buf.len()>=49*32768{s8.same(&buf);h.update(&buf);buf.clear();}}if !buf.is_empty(){s8.same(&buf);h.update(&buf);}let common=t.elapsed().as_secs_f64();
 let mut encoded=Vec::new();let mut readers=Vec::new();for ts in &tails{let mut b=Vec::new();for o in ts{b.extend_from_slice(&record49(o));}let mut hj=h.clone();hj.update(&b);readers.push(hj.finalize_xof());encoded.extend_from_slice(&b);}s8.different(&encoded,96*49);s8.finalize();
 let t=Instant::now();let keys=s8.squeeze(NUM_TESTS*64);for j in 0..8{ops[start..].copy_from_slice(&tails[j]);let protected=fiat_shamir_seed(&ops);let mut a=protected.clone();let mut b=readers[j].clone();let mut aa=[0;200];let mut bb=[0;200];XofReader::read(&mut a,&mut aa);XofReader::read(&mut b,&mut bb);assert_eq!(aa,bb,"protected complete transcript differs lane{j}");readers[j]=protected;let mut expected=vec![0;NUM_TESTS*64];XofReader::read(&mut readers[j],&mut expected);assert_eq!(expected,&keys[j*NUM_TESTS*64..(j+1)*NUM_TESTS*64],"all9024 scalar-pairs transcript mismatch lane{j}");}println!("FIAT_HASH_EQUAL lanes=8 ops={} common_prefix_ops={start} nonce_tail_ops=96 bytes_per_op=49 keypairs_per_lane={NUM_TESTS} keybytes_per_lane={} common_hash_seconds={common:.6} key_verify_seconds={:.6}",ops.len(),NUM_TESTS*64,t.elapsed().as_secs_f64());
 // Keep the exact first-MR states for protected scalar replay and random
 // nonconsecutive batch selection. No point-generation draws occur later.
 let mut selected_ctx=s8.clone_ctx();let scalar_start=readers.clone();let mut rng=vec![Row([0;8]);p.rng_count];let mut rngsecs=f64::INFINITY;for rep in 0..5{let mut rc=s8.clone_ctx();let t=Instant::now();assert_eq!(unsafe{shake8_words8(rc.0,rng.as_mut_ptr().cast(),rng.len())},0);let dt=t.elapsed().as_secs_f64();rngsecs=rngsecs.min(dt);println!("SHAKE8_PREALLOC_TIMING rep={rep} eight_batch_seconds={dt:.6}");}
 for j in 0..8{let mut bytes=vec![0;p.rng_count*8];let mut r=readers[j].clone();XofReader::read(&mut r,&mut bytes);for i in 0..p.rng_count{assert_eq!(rng[i].0[j],u64::from_le_bytes(bytes[8*i..8*i+8].try_into().unwrap()),"MR word lane{j} ordinal{i}");}}
 println!("SHAKE8_MR_EQUAL lanes=8 words_per_lane={} bytes_per_lane={} seconds={rngsecs:.6} ms_per_batch={:.4}",p.rng_count,p.rng_count*8,rngsecs*125.0);
 let t=Instant::now();let curve=secp256k1();let mut init=State{q:vec![Row([0;8]);nq as usize],b:vec![Row([0;8]);nb as usize],p:Row([0;8])};for j in 0..8{let mut junk=reader(0);let mut s=Simulator::new(nq as usize,nb as usize,&mut junk);for lane in 0..64{let off=j*NUM_TESTS*64+lane*64;let k1=U256::from_le_bytes::<32>(keys[off..off+32].try_into().unwrap());let k2=U256::from_le_bytes::<32>(keys[off+32..off+64].try_into().unwrap());let a=curve.mul(curve.gx,curve.gy,k1);let b=curve.mul(curve.gx,curve.gy,k2);assert!(a.0!=b.0&&!a.0.is_zero()&&!b.0.is_zero());for(k,v)in[a.0,a.1,b.0,b.1].iter().enumerate(){s.set_register(&regs[k],*v,lane);}}for i in 0..nq as usize{init.q[i].0[j]=s.qubits[i];}for i in 0..nb as usize{init.b[i].0[j]=s.bits[i];}}println!("FIAT_POINT_SETUP first_batch_per_lane=64 seconds={:.6}",t.elapsed().as_secs_f64());
 let mut ws=workspace(&p);let mut result=init.clone();let mut kernel=f64::INFINITY;for rep in 0..5{result=init.clone();let t=Instant::now();run_prepared(&p,&mut result,&rng,&mut ws).unwrap();let dt=t.elapsed().as_secs_f64();kernel=kernel.min(dt);println!("FIAT_KERNEL_PREPARED_TIMING rep={rep} eight_batch_seconds={dt:.6}");}
 let pf=specialize(&p);let mut fast_kernel=f64::INFINITY;for rep in 0..5{let mut fr=init.clone();let t=Instant::now();run_fast(&pf,&mut fr,&rng,&mut ws).unwrap();let dt=t.elapsed().as_secs_f64();assert!(fr==result,"specialized full-state mismatch");fast_kernel=fast_kernel.min(dt);println!("FIAT_FAST_KERNEL_TIMING rep={rep} eight_batch_seconds={dt:.6}");}println!("SPECIALIZED_FULL_STATE_EQUAL shots=512 kernel_seconds={fast_kernel:.6} rng_plus_kernel_seconds={:.6}",fast_kernel+rngsecs);
 let t=Instant::now();for j in 0..8{ops[start..].copy_from_slice(&tails[j]);let mut r=CountRng{inner:readers[j].clone(),bytes:0};let mut s=Simulator::new(nq as usize,nb as usize,&mut r);for i in 0..nq as usize{s.qubits[i]=init.q[i].0[j];}for i in 0..nb as usize{s.bits[i]=init.b[i].0[j];}s.apply_iter(ops.iter());for i in 0..nq as usize{assert_eq!(s.qubits[i],result.q[i].0[j],"fiat qubit{i} lane{j}");}for i in 0..nb as usize{assert_eq!(s.bits[i],result.b[i].0[j],"fiat bit{i} lane{j}");}assert_eq!(s.phase,result.p.0[j],"fiat phase lane{j}");drop(s);assert_eq!(r.bytes,p.rng_count*8);}let protected=t.elapsed().as_secs_f64();
 println!("FIAT_FULL_PAIRED_PASS shots=512 all_qubits={nq} all_bits={nb} phase=true rng_draws={} kernel_seconds={kernel:.6} protected8_seconds={protected:.6} rng8_seconds={rngsecs:.6} combined_seconds={:.6} score=NONE nonce_search=false",p.rng_count,kernel+rngsecs);
 let t=Instant::now();for j in 0..8{let mut rr=readers[j].clone();let mut ss=FastSimulator::new(nq as usize,nb as usize,&mut rr);for i in 0..nq as usize{ss.qubits[i]=init.q[i].0[j];}for i in 0..nb as usize{ss.bits[i]=init.b[i].0[j];}ss.apply(&p);for i in 0..nq as usize{assert_eq!(ss.qubits[i],result.q[i].0[j]);}for i in 0..nb as usize{assert_eq!(ss.bits[i],result.b[i].0[j]);}assert_eq!(ss.phase,result.p.0[j]);}let compactsecs=t.elapsed().as_secs_f64();println!("FIAT_RECURRING_BENCH compact8_seconds={compactsecs:.6} SIMD8_rng_plus_kernel_seconds={:.6} speedup={:.6} allocation_excluded=true maxstack_scan_excluded=true input_curve_setup_excluded=true",kernel+rngsecs,compactsecs/(kernel+rngsecs));
 // Nonconsecutive arbitrary batch-index support for the advisory scheduler.
 // Selection returns no correctness judgments, just exact MR words.
 let offsets=[0,1,2,3,1,2,0,3].map(|i|i*p.rng_count);let t=Instant::now();let selected=selected_ctx.select(offsets,p.rng_count);let selectsecs=t.elapsed().as_secs_f64();for j in 0..8{let mut r=scalar_start[j].clone();let mut discard=vec![0;65536];let mut left=offsets[j]*8;while left>0{let n=left.min(discard.len());XofReader::read(&mut r,&mut discard[..n]);left-=n;}let mut bytes=vec![0;p.rng_count*8];XofReader::read(&mut r,&mut bytes);for i in 0..p.rng_count{assert_eq!(selected[i].0[j],u64::from_le_bytes(bytes[8*i..8*i+8].try_into().unwrap()));}}
 println!("SHAKE8_SELECTED_PASS batch_indices=0,1,2,3,1,2,0,3 words_per_lane={} seconds={selectsecs:.6}",p.rng_count);
}
